//! `eforge onboard` and `eforge docs` commands — deterministic repository documentation & onboarding generator.

use std::fs;
use std::path::{Path, PathBuf};

use forge_core::{ForgeError, Repository};
use serde::{Deserialize, Serialize};

use crate::cli::OutputFormat;
use crate::commands::graph::run_graph;
use crate::commands::scan::{execute_scan, ScanOptions};

const GENERATED_HEADER: &str =
    "<!-- GENERATED BY ELCODE FORGE (eforge). DO NOT EDIT MANUALLY. -->\n\n";

/// Summary of generated documentation files produced by `eforge onboard` / `eforge docs`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct GeneratedDocsBundle {
    /// Target directory where documentation files were written.
    pub output_dir: PathBuf,
    /// Deterministic list of generated file paths.
    pub files_written: Vec<PathBuf>,
}

/// Generates the 5 deterministic onboarding & architecture Markdown documents inside `output_dir`:
/// - `architecture.md`
/// - `modules.md`
/// - `dependencies.md`
/// - `onboarding.md`
/// - `risks.md`
pub fn generate_onboarding_docs(
    repo_root: &Path,
    output_dir: &Path,
) -> Result<GeneratedDocsBundle, ForgeError> {
    fs::create_dir_all(output_dir).map_err(|source| ForgeError::Io {
        path: output_dir.to_path_buf(),
        source,
    })?;

    let scan_opts = ScanOptions {
        repo_root: repo_root.to_path_buf(),
        incremental: false,
        format: OutputFormat::Json,
    };
    let (repo, _) = execute_scan(&scan_opts)?;
    let mermaid_graph = run_graph(repo_root, OutputFormat::Markdown)?;

    let docs = [
        (
            "architecture.md",
            build_architecture_doc(&repo, &mermaid_graph),
        ),
        ("modules.md", build_modules_doc(&repo)),
        ("dependencies.md", build_dependencies_doc(&repo)),
        ("onboarding.md", build_onboarding_doc(&repo)),
        ("risks.md", build_risks_doc(&repo)),
    ];

    let mut files_written = Vec::with_capacity(docs.len());
    for (filename, content) in docs {
        let target = output_dir.join(filename);
        fs::write(&target, content).map_err(|source| ForgeError::Io {
            path: target.clone(),
            source,
        })?;
        files_written.push(target);
    }

    Ok(GeneratedDocsBundle {
        output_dir: output_dir.to_path_buf(),
        files_written,
    })
}

fn build_architecture_doc(repo: &Repository, mermaid_graph: &str) -> String {
    let mut md = String::from(GENERATED_HEADER);
    md.push_str(&format!("# Architecture Overview — `{}`\n\n", repo.name));
    md.push_str(&format!(
        "- **Languages:** `{}`\n- **Frameworks:** `{}`\n- **Package Managers:** `{}`\n- **Total Files:** {}\n- **Logical Modules:** {}\n\n",
        repo.detected_languages.join(", "),
        repo.detected_frameworks.join(", "),
        repo.package_managers.join(", "),
        repo.files.len(),
        repo.modules.len()
    ));
    md.push_str(mermaid_graph);
    md
}

fn build_modules_doc(repo: &Repository) -> String {
    let mut md = String::from(GENERATED_HEADER);
    md.push_str(&format!("# Module Map — `{}`\n\n", repo.name));
    if repo.modules.is_empty() {
        md.push_str("_No logical modules inferred._\n");
        return md;
    }

    for module in &repo.modules {
        md.push_str(&format!("## Module `{}`\n\n", module.id));
        md.push_str(&format!(
            "- **Root Path:** `{}`\n- **Files ({}):** `{}`\n- **Imports:** `{}`\n- **Exports:** `{}`\n\n",
            module.root_path,
            module.files.len(),
            module.files.join("`, `"),
            if module.imports.is_empty() {
                "none".to_string()
            } else {
                module.imports.join("`, `")
            },
            if module.exports.is_empty() {
                "none".to_string()
            } else {
                module.exports.join("`, `")
            }
        ));
    }
    md
}

fn build_dependencies_doc(repo: &Repository) -> String {
    let mut md = String::from(GENERATED_HEADER);
    md.push_str(&format!("# Dependency Catalog — `{}`\n\n", repo.name));
    if repo.dependencies.is_empty() {
        md.push_str("_No external dependencies declared._\n");
        return md;
    }

    md.push_str("| Package | Version Req | Resolved | Scope |\n| :--- | :--- | :--- | :--- |\n");
    for dep in &repo.dependencies {
        md.push_str(&format!(
            "| `{}` | `{}` | `{}` | {} |\n",
            dep.name,
            dep.version_req,
            dep.resolved_version.as_deref().unwrap_or("-"),
            if dep.is_dev { "dev" } else { "prod" }
        ));
    }
    md
}

fn build_onboarding_doc(repo: &Repository) -> String {
    let mut md = String::from(GENERATED_HEADER);
    md.push_str(&format!(
        "# Developer Onboarding Guide — `{}`\n\n",
        repo.name
    ));
    md.push_str("## 1. Project Identity\n\n");
    md.push_str(&format!(
        "- **Name:** `{}`\n- **Primary Stack:** `{}` (`{}`)\n- **Package Manager:** `{}`\n\n",
        repo.name,
        repo.detected_languages.join(", "),
        repo.detected_frameworks.join(", "),
        repo.package_managers.join(", ")
    ));

    let entrypoints: Vec<&str> = repo
        .files
        .iter()
        .map(|f| f.relative_path.as_str())
        .filter(|p| {
            p.contains("index.")
                || p.contains("main.")
                || p.contains("app.")
                || p.starts_with("src/pages/")
                || p.starts_with("src/app/")
        })
        .collect();

    md.push_str("## 2. Application Entrypoints\n\n");
    if entrypoints.is_empty() {
        md.push_str("- Inspect `src/` for primary entrypoints.\n\n");
    } else {
        for ep in entrypoints {
            md.push_str(&format!("- `{ep}`\n"));
        }
        md.push('\n');
    }

    let test_files: Vec<&str> = repo
        .files
        .iter()
        .filter(|f| f.is_test)
        .map(|f| f.relative_path.as_str())
        .collect();
    md.push_str("## 3. Verification & Tests\n\n");
    md.push_str(&format!(
        "- **Detected Test Files:** {}\n- Run `eforge doctor` and `eforge scan` before opening a Pull Request.\n",
        test_files.len()
    ));
    md
}

fn build_risks_doc(repo: &Repository) -> String {
    let mut md = String::from(GENERATED_HEADER);
    md.push_str(&format!(
        "# Engineering Health & Risk Register — `{}`\n\n",
        repo.name
    ));
    if let Some(health) = &repo.health {
        md.push_str(&format!(
            "## Overall Health Score: **{}/100**\n\n",
            health.overall
        ));
        md.push_str("| Dimension | Score | Weight | Notes |\n| :--- | :---: | :---: | :--- |\n");
        for dim in &health.dimensions {
            md.push_str(&format!(
                "| `{}` | {}/100 | {}% | {} |\n",
                dim.dimension,
                dim.score,
                dim.weight_pct,
                dim.reasons.join("; ")
            ));
        }
        md.push('\n');
    }

    md.push_str(&format!("## Active Findings ({})\n\n", repo.findings.len()));
    for finding in &repo.findings {
        md.push_str(&format!(
            "- **[{:?}] `{}`** — {} (`{}`)\n  - *Recommendation:* {}\n",
            finding.severity,
            finding.rule_id,
            finding.title,
            finding.evidence,
            finding.recommendation
        ));
    }
    md
}

#[cfg(test)]
mod tests {
    use std::env;
    use std::fs;
    use std::path::PathBuf;
    use std::time::{SystemTime, UNIX_EPOCH};

    use super::{generate_onboarding_docs, GENERATED_HEADER};

    fn fixture_next_app_dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("..")
            .join("..")
            .join("fixtures")
            .join("next-app")
    }

    #[test]
    fn generates_all_five_onboarding_and_architecture_docs_with_generated_banner() {
        let nanos = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|d| d.as_nanos())
            .unwrap_or(0);
        let out_dir = env::temp_dir().join(format!("eforge_onboard_test_{nanos}"));

        let res = generate_onboarding_docs(&fixture_next_app_dir(), &out_dir);
        assert!(res.is_ok());

        if let Ok(bundle) = res {
            assert_eq!(bundle.files_written.len(), 5);
            for file_path in &bundle.files_written {
                assert!(file_path.is_file());
                let content = fs::read_to_string(file_path).unwrap_or_default();
                assert!(content.starts_with(GENERATED_HEADER));
            }
        }

        let _ = fs::remove_dir_all(&out_dir);
    }
}
